package fixture

import "testing"

func TestFizzBuzz(t *testing.T) {
	cases := map[int]string{15: "FizzBuzz", 3: "Fizz", 5: "Buzz", 7: "7"}
	for n, want := range cases {
		if got := FizzBuzz(n); got != want {
			t.Fatalf("FizzBuzz(%d) = %q, want %q", n, got, want)
		}
	}
}
